function validate([words, target]) {
  if (words.length < 1 || words.length > 100) return 'words needs 1 to 100 strings.';
  let total = 0;
  for (const word of words) {
    if (word.length < 1 || word.length > 5000) return 'Each word has 1 to 5000 letters.';
    if (!/^[a-z]+$/.test(word)) return 'Words contain only lowercase English letters.';
    total += word.length;
  }
  if (total > 100000) return 'The words have at most 10^5 letters in total.';
  if (target.length < 1 || target.length > 5000) return 'target has 1 to 5000 letters.';
  if (!/^[a-z]+$/.test(target)) return 'target contains only lowercase English letters.';
  return null;
}

