function minValidStrings(words, target) {
  // Breadth-first search over how many letters are built; every non-empty piece that some word starts with is an edge.
  const n = target.length;
  const steps = new Array(n + 1).fill(-1);
  steps[0] = 0;
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    const at = queue[q];
    for (let next = at + 1; next <= n; next++) {
      const piece = target.slice(at, next);
      if (steps[next] === -1 && words.some(w => w.startsWith(piece))) {
        steps[next] = steps[at] + 1;
        queue.push(next);
      }
    }
  }
  return steps[n];
}

