function generate(rand, size) {
  const large = size === 'large';
  const pick = list => list[Math.floor(rand() * list.length)];
  const letters = 'abcd'.slice(0, large ? 2 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 3));
  const text = length => Array.from({ length }, () => pick(letters)).join('');
  const count = large ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  // A few long words on large inputs give long pieces; the rest stay short.
  const words = Array.from({ length: count }, () => text(1 + Math.floor(rand() * (large ? (rand() < 0.1 ? 5000 : 300) : 5))));
  const length = large ? 5000 : 1 + Math.floor(rand() * 10);
  let target = '';
  if (large || rand() < 0.65) {
    // Glue random prefixes of the words together, so the target can usually be formed.
    while (target.length < length) {
      const word = pick(words);
      target += word.slice(0, 1 + Math.floor(rand() * word.length));
    }
    target = target.slice(0, length);
  } else {
    target = text(length);
  }
  return [words, target];
}
